// 親の主星 × 子の主星 の相性マトリクス
// 10×10 = 100パターンのアドバイステキスト

import type { MainStar } from '@/lib/sanmeigaku';

export interface CompatibilityAdvice {
  compatibility: '◎' | '○' | '△';
  summary: string;
  howToApproach: string;
  ngAction: string;
  detailedAdvice: string;
  dailyRoutine: string[];
  conflictResolution: string;
  specialMoment: string;
  growthOpportunity: string;
}

// 相性データ生成ヘルパー
function advice(
  compatibility: '◎' | '○' | '△',
  summary: string,
  howToApproach: string,
  ngAction: string,
  detailedAdvice: string,
  dailyRoutine: string[],
  conflictResolution: string,
  specialMoment: string,
  growthOpportunity: string,
): CompatibilityAdvice {
  return { compatibility, summary, howToApproach, ngAction, detailedAdvice, dailyRoutine, conflictResolution, specialMoment, growthOpportunity };
}

